from thefuck.utils import sudo_support
import re


@sudo_support
def match(command, settings):
    script_text = command.script
    err_text = command.stderr
    return ('mkdir' in script_text) and ('No such file or directory' in err_text)


@sudo_support
def get_new_command(command, settings):
    return re.sub('^mkdir (.*)', 'mkdir -p \\1', command.script)
